// TEMPORARY review-verification script (deleted after review) — simulates
// the macOS TMPDIR shape (/var -> private/var symlink) to check whether
// resolveWithinAllowedBase falsely rejects not-yet-existing paths.
import 'dart:io';
import 'package:dmtools/dmtools.dart';

void main() {
  for (final mode in ['planned', 'existing']) {
    final real = Directory.systemTemp.createTempSync('sim_private');
    final link = Link(
        '${Directory.systemTemp.path}/sim_var_${DateTime.now().microsecondsSinceEpoch}')
      ..createSync(real.path);
    final tmpdir = '${link.path}/sub/T'; // lexical TMPDIR analog
    Directory(tmpdir).createSync(recursive: true);
    final base = Directory('$tmpdir/base')..createSync();
    try {
      final target = '${base.path}/newfile.txt'; // does NOT exist yet
      if (mode == 'existing') File(target).writeAsStringSync('x');
      try {
        final resolved = resolveWithinAllowedBase(target, base.path);
        print('$mode: ALLOWED -> $resolved');
      } catch (e) {
        print('$mode: REJECTED -> ${e.toString().replaceAll('\n', ' ')}');
      }
    } finally {
      link.deleteSync();
      real.deleteSync(recursive: true);
    }
  }
}

