// TEMPORARY review-verification script (deleted after review) — replicates
// the macOS TMPDIR mechanics: on macOS TMPDIR=/var/folders/... where /var
// is a symlink to private/var, so Directory.systemTemp.path is lexically
// different from its canonical form. We mirror that with a symlink OUTSIDE
// /tmp so no real prefix rescues the check.
import 'dart:io';
import 'package:dmtools/dmtools.dart';

void main() {
  final home = Directory('/home/ubuntu');
  final real = home.createTempSync('sim_private');
  final link = Link('${home.path}/sim_var_${DateTime.now().microsecondsSinceEpoch}')
    ..createSync(real.path);
  final tmpdir = '${link.path}/sub/T'; // lexical TMPDIR analog (=/var/folders/.../T)
  Directory(tmpdir).createSync(recursive: true);
  final base = Directory('$tmpdir/base')..createSync();
  print('systemTemp-like lexical: $tmpdir');
  print('canonical(systemTemp):   ${Directory(tmpdir).resolveSymbolicLinksSync()}');
  for (final mode in ['planned', 'existing']) {
    try {
      final target = '${base.path}/newfile.txt'; // does NOT exist yet
      if (mode == 'existing') File(target).writeAsStringSync('x');
      try {
        final resolved = resolveWithinAllowedBase(target, base.path);
        print('$mode: ALLOWED -> $resolved');
      } catch (e) {
        print('$mode: REJECTED -> ${e.toString().replaceAll('\n', ' ')}');
      }
    } finally {
      link.deleteSync();
      real.deleteSync(recursive: true);
    }
  }
}

