// TEMPORARY review-verification script (deleted after review) — checks
// whether a planned write THROUGH an in-base symlinked parent escapes the
// sandbox: resolveWithinAllowedBase('sub/new.txt', base) where base/sub
// symlinks outside, then the caller materializes the file.
import 'dart:io';
import 'package:dmtools/dmtools.dart';

void main() {
  final base = Directory.systemTemp.createTempSync('sim_esc_base');
  final outside = Directory.systemTemp.createTempSync('sim_esc_out');
  try {
    Link('${base.path}/sub').createSync(outside.path);
    final planned = '${base.path}/sub/escape.txt'; // does NOT exist yet

    String resolved;
    try {
      resolved = resolveWithinAllowedBase(planned, base.path);
      print('CHECK: ALLOWED -> $resolved');
    } catch (e) {
      print('CHECK: REJECTED -> $e');
      return;
    }
    // What the caller (file_write / FileToolExecutor.write) does next:
    final parent = Directory(resolved).parent;
    if (!parent.existsSync()) parent.createSync(recursive: true);
    File(resolved).writeAsStringSync('escaped');
    final landed = '${outside.path}/escape.txt';
    print('MATERIALIZED outside: ${File(landed).existsSync()} at $landed');
  } finally {
    Link('${base.path}/sub').deleteSync();
    base.deleteSync(recursive: true);
    outside.deleteSync(recursive: true);
  }
}

