```dart
String _canonicalizePath(String path) {
  var current = path;
  final trail = <String>[];
  while (true) {
    try {
      return '${Directory(current).resolveSymbolicLinksSync()}'
          '${trail.isEmpty ? '' : '/${trail.reversed.join('/')}'}';
