+        expect(await f.executor.delete(target), isTrue);
+      } finally {
+        other.deleteSync(recursive: true);
+      }
+    });
+  });
+}
+
+/// Copy validates BOTH endpoints: an outside source would leak content
+/// into the base, an outside destination would smuggle it out.
