          a['path'] as String,
          (a['data'] as Map).cast<String, dynamic>(),
        ),
    'file_exists_in_path': (a) => existsInPath(
          a['path'] as String,
          a['filename'] as String,
        ),
    'file_get_size': (a) => getSize(a['path'] as String),
    'file_watch': (a) => watch(a['path'] as String),
