+      'writeLines': (e, p) => e.writeLines(p, const ['x']),
+      'append': (e, p) => e.append(p, 'x'),
+      'getFileInfo': (e, p) => e.getFileInfo(p),
+      'readJson': (e, p) => e.readJson(p),
+      'getSize': (e, p) => e.getSize(p),
+      'watch': (e, p) => e.watch(p),
