import 'dart:io';
import 'package:dmtools/dmtools.dart';

void main(List<String> args) {
  final mode = args.first;
  final real = Directory.systemTemp.createTempSync('sim_private');
  final link = Link('${Directory.systemTemp.path}/sim_var_${DateTime.now().microsecondsSinceEpoch}')
    ..createSync(real.path);
