    final planned = '${base.path}/sub/escape.txt'; // does NOT exist
    // Sanity: the base is NOT inside a git repo, so the git-root branch
    // cannot rescue; /home/ubuntu/... is outside the system tmpdir.
    try {
      final resolved = resolveWithinAllowedBase(planned, base.path);
      print('escape2: ALLOWED -> $resolved (VULNERABLE)');
    } catch (e) {
      print('escape2: REJECTED -> ${e.toString().replaceAll('\n', ' ').substring(0, 90)}');
