import 'package:dmtools/dmtools.dart';

void main() {
  final home = Directory('/home/ubuntu');
  final real = home.createTempSync('sim_private');
  final link = Link('${home.path}/sim_var_${DateTime.now().microsecondsSinceEpoch}')
    ..createSync(real.path);
  final tmpdir = '${link.path}/sub/T'; // lexical TMPDIR analog (=/var/folders/.../T)
