{"content":"// Simulates the macOS TMPDIR shape (/var -> private/var symlink) to test
// whether resolveWithinAllowedBase falsely rejects not-yet-existing paths
// under the system temp dir. Standalone script for PR #366 review.
import 'dart:io';
import 'package:dmtools/dmtools.dart';

void main(List<String> args) {
  final mode = args.first;
  final real = Directory.systemTemp.createTempSync('sim_private');
  final link = Link('${Directory.systemTemp.path}/sim_var_${DateTime.now().microsecondsSinceEpoch}')
    ..createSync(real.path);
  // TMPDIR=/tmp/sim_var_xxx/sub/T  (lexical) vs canonical /tmp/sim_private/sub/T
  final tmpdir = '${link.path}/sub/T';
  Directory(tmpdir).createSync(recursive: true);
  final base = Directory('$tmpdir/base')..createSync();
  try {
    final target = '${base.path}/newfile.txt'; // does NOT exist yet
    if (mode == 'existing') File(target).writeAsStringSync('x');
    try {
      final resolved = resolveWithinAllowedBase(target, base.path);
      print('ALLOWED -> $resolved');
    } catch (e) {
      print('REJECTED: ${e.toString().replaceAll('\n', ' ')}');
    }
  } finally {
    link.deleteSync();
    real.deleteSync(recursive: true);
  }
}
