+    });
+  });
+}
+
+/// The blocked side of the file-path sandbox — every rejection carries the
+/// Java `FileTools` spec wording ("Path traversal attempt blocked").
+void resolveBlockedTests() {
+  group('resolveWithinAllowedBase — blocked paths', () {
+    late Directory base;
