{"content":"// TEMPORARY re-review verification (deleted after) — re-runs the two
// attacks from the blocking review finding against the REWORKED code:
// 1. escape: planned write through in-base symlinked parent -> must REJECT
// 2. macOS-shaped tmpdir (symlink above TMPDIR, TMPDIR not under /tmp):
//    planned write -> must ALLOW
import 'dart:io';
import 'package:dmtools/dmtools.dart';

void attackEscape() {
  final base = Directory.systemTemp.createTempSync('rv_esc_base');
  final outside = Directory.systemTemp.createTempSync('rv_esc_out');
  try {
    Link('${base.path}/sub').createSync(outside.path);
    final planned = '${base.path}/sub/escape.txt'; // does NOT exist
    try {
      final resolved = resolveWithinAllowedBase(planned, base.path);
      print('escape: ALLOWED -> $resolved (VULNERABLE)');
      final parent = Directory(resolved).parent;
      if (!parent.existsSync()) parent.createSync(recursive: true);
      File(resolved).writeAsStringSync('x');
      print('escape: MATERIALIZED=${File('${outside.path}/escape.txt').existsSync()}');
    } catch (e) {
      print('escape: REJECTED -> ${e.toString().replaceAll('\n', ' ').substring(0, 80)}');
      print('escape: landed=${File('${outside.path}/escape.txt').existsSync()} (want false)');
    }
  } finally {
    Link('${base.path}/sub').deleteSync();
    base.deleteSync(recursive: true);
    outside.deleteSync(recursive: true);
  }
}

void attackMacTmpdir() {
  final home = Directory('/home/ubuntu');
  final real = home.createTempSync('rv_sim_private');
  final link = Link('${home.path}/rv_sim_var')..createSync(real.path);
  try {
    final tmpdir = '${link.path}/sub/T'; // lexical TMPDIR analog
    Directory(tmpdir).createSync(recursive: true);
    final base = Directory('$tmpdir/base')..createSync();
    final target = '${base.path}/newfile.txt'; // does NOT exist
    try {
      final resolved = resolveWithinAllowedBase(target, base.path);
      print('macTmpdir: ALLOWED -> $resolved (want ALLOWED)');
    } catch (e) {
      print('macTmpdir: REJECTED (REGRESSION) -> ${e.toString().replaceAll('\n', ' ').substring(0, 100)}');
    }
  } finally {
    link.deleteSync();
    real.deleteSync(recursive: true);
  }
}

void main() {
  attackEscape();
  attackMacTmpdir();
}
